response.text:
{
  "steps": [
    {
      "id": "step-1",
      "goal": "List all unread invoice emails in the AP mailbox",
      "allowed_tools": ["mail.list"],
      "done_criterion": "All unread AP mailbox invoice email IDs are collected and available for processing."
    },
    {
      "id": "step-2",
      "goal": "Open each unread invoice email, save every invoice attachment to the Run's working folder, and mark the email read before any LedgerLite action",
      "allowed_tools": ["mail.read", "files.write", "mail.mark_read"],
      "done_criterion": "All invoice attachments from unread AP mailbox emails are saved in the working folder and their source emails are marked read; no LedgerLite/ERP tools were used."
    },
    {
      "id": "step-3",
      "goal": "Extract invoice fields from each saved attachment and record missing or unreadable fields as open questions without guessing",
      "allowed_tools": ["files.extract", "files.write"],
      "done_criterion": "Vendor name, invoice number, amount, purchase order, goods receipt, invoice date, and payment terms are extracted for each attachment; missing or unreadable values are recorded as open questions and no guessed values are used."
    },
    {
      "id": "step-4",
      "goal": "Verify each extracted vendor exists in LedgerLite and is not blocked",
      "allowed_tools": ["erp.list_vendors", "erp.get_vendor", "files.write"],
      "done_criterion": "Every extracted vendor is confirmed present and not blocked in LedgerLite, or any missing or blocked vendor is recorded as an exception/open question."
    },
    {
      "id": "step-5",
      "goal": "Check for duplicate invoices in LedgerLite by vendor and invoice number and exclude any invoice already present or paid from filing",
      "allowed_tools": ["erp.list_invoices", "erp.get_invoice", "files.write"],
      "done_criterion": "All extracted invoices have been checked against LedgerLite; duplicate and already-paid invoices are recorded and removed from the filing path."
    },
    {
      "id": "step-6",
      "goal": "Match each remaining invoice to its purchase order and goods receipt and compare the invoice amount to the purchase order amount",
      "allowed_tools": ["erp.list_purchase_orders", "erp.get_purchase_order", "erp.get_goods_receipt", "files.write"],
      "done_criterion": "Each remaining invoice has a matched purchase order and goods receipt; any amount mismatch with the purchase order is recorded as an exception and is not filed."
    },
    {
      "id": "step-7",
      "goal": "File validated non-duplicate, non-exception invoices in LedgerLite against their purchase order and goods receipt",
      "allowed_tools": ["erp.file_invoice"],
      "done_criterion": "Every eligible invoice is filed in LedgerLite against its matched purchase order and goods receipt with a returned invoice record."
    },
    {
      "id": "step-8",
      "goal": "Schedule payments only in USD and only through LedgerLite for each validated invoice, using the over-spend-limit approval gate for any payment above 10,000.00 USD and never paying a blocked vendor",
      "allowed_tools": ["erp.schedule_payment", "files.write"],
      "done_criterion": "Each due validated invoice has a USD payment scheduled through LedgerLite if at or below 10,000.00 USD, or prepared for human approval if above 10,000.00 USD; non-USD or blocked-vendor payments are recorded as exceptions and not scheduled."
    },
    {
      "id": "step-9",
      "goal": "Move source PDFs and scans to the processed folder and record their archived location",
      "allowed_tools": ["files.move", "files.write"],
      "done_criterion": "All source PDFs and scans are moved to the processed folder and their locations are recorded."
    },
    {
      "id": "step-10",
      "goal": "Verify LedgerLite and the filesystem confirm each filed invoice record exists with the correct amount and status, and each source document is archived",
      "allowed_tools": ["erp.get_invoice", "files.list"],
      "done_criterion": "Every filed invoice is confirmed in LedgerLite with the correct amount and status, and its source document is present in the processed folder/archive."
    }
  ]
}
